// The server (Python, app/quant/indicators.py) and the chart (this TS code) must compute identical
// values, otherwise backtest signals wouldn't match what the chart shows. The fixture is generated by
// the Python side: `cd server && .venv/bin/python -m app.quant.fixtures`.
import { describe, expect, it } from 'vitest'
import fixture from '../../../shared/fixtures/indicators.json'
import * as calc from './calc'
import { ema, sma, type Series } from './math'

const { close, high, low } = fixture.input
const bars = { time: close.map((_, i) => i), open: close, high, low, close, volume: close.map(() => 1) }

function expectSame(actual: Series, expected: (number | null)[]) {
  expect(actual).toHaveLength(expected.length)
  actual.forEach((v, i) => {
    if (expected[i] === null) expect(v, `index ${i}`).toBeNull()
    else expect(v, `index ${i}`).toBeCloseTo(expected[i] as number, 9)
  })
}

describe('TS indicators match the Python implementation', () => {
  const o = fixture.output
  it('sma / ema', () => {
    expectSame(sma(close, 20), o.sma20)
    expectSame(ema(close, 12), o.ema12)
  })
  it('rsi', () => {
    expectSame(calc.rsi(close, 14), o.rsi14)
    expectSame(calc.rsi(close, 2), o.rsi2)
  })
  it('atr', () => expectSame(calc.atr(bars, 14), o.atr14))
  it('bollinger', () => {
    const bb = calc.bollinger(close, 20, 2)
    expectSame(bb.upper, o.bb_upper)
    expectSame(bb.lower, o.bb_lower)
  })
  it('donchian', () => {
    const dc = calc.donchian(bars, 20, 10)
    expectSame(dc.upper, o.dc_upper)
    expectSame(dc.lower, o.dc_lower)
  })
})
